fn dump(node: Node, src: &str, depth: usize) {
    let text = &src[node.start_byte()..node.end_byte()];
    let text_short: String = text.chars().take(30).collect::<String>().replace('\n', "\\n");
    println!(
        "{:indent$}{} [{}..{}] err={} miss={} text={:?}",
        "", node.kind(), node.start_byte(), node.end_byte(),
        node.is_error(), node.is_missing(), text_short,
        indent = depth * 2
    );
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        dump(child, src, depth + 1);
    }
}

fn main() {
    let cases = [
        "x = 'abc;\n",
        "x = 'don''t stop\n",
        "'abc\n",
        "disp('abc\n",
        "x = \"abc;\n",
        "s = \"\n",
        "y = \"a\nb\nc\";\n",
        "x = (1:5)';\n",
        "x = A.'; y = B';\n",
        "x = 'abc; y = 2;\n",
        "foo('a', 'b\n",
        "x = \"abc\n",
        "x = ';\n",
        "x = 'abc'; % ok\n",
    ];
    for src in cases {
        let mut parser = Parser::new();
        parser.set_language(&tree_sitter_matlab::LANGUAGE.into()).unwrap();
        let tree = parser.parse(src, None).unwrap();
        println!("===== {:?}", src);
        dump(tree.root_node(), src, 0);
    }
}
EOF
